#include <assert.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>

#define MAX_STUDENTS 3
#define NAME_SIZE 64

struct Student {
    int id;
    char name[NAME_SIZE];
    double marks;
};

enum Result { OK, DUPLICATE_ID, FULL, NOT_FOUND, INVALID };

static int valid_student(const struct Student *s) {
    return s != NULL && s->id > 0 && s->name[0] != '\0'
        && strlen(s->name) < NAME_SIZE
        && s->marks >= 0.0 && s->marks <= 100.0;
}

static size_t find_student(const struct Student students[], size_t count, int id) {
    size_t i;
    for (i = 0; i < count; ++i) {
        if (students[i].id == id) return i;
    }
    return count;
}

static enum Result add_student(struct Student students[], size_t *count,
                               const struct Student *student) {
    size_t i;
    if (students == NULL || count == NULL || student == NULL
        || *count > MAX_STUDENTS || !valid_student(student)) return INVALID;
    if (*count == MAX_STUDENTS) return FULL;
    for (i = 0; i < *count; ++i) {
        if (students[i].id == student->id) return DUPLICATE_ID;
    }
    students[*count] = *student;
    ++(*count);
    return OK;
}

static enum Result update_marks(struct Student students[], size_t count,
                                int id, double marks) {
    size_t index;
    if (students == NULL || marks < 0.0 || marks > 100.0) return INVALID;
    index = find_student(students, count, id);
    if (index == count) return NOT_FOUND;
    students[index].marks = marks;
    return OK;
}

static enum Result delete_student(struct Student students[], size_t *count, int id) {
    size_t index;
    size_t i;
    if (students == NULL || count == NULL || *count > MAX_STUDENTS) return INVALID;
    index = find_student(students, *count, id);
    if (index == *count) return NOT_FOUND;
    for (i = index; i + 1U < *count; ++i) students[i] = students[i + 1U];
    --(*count);
    return OK;
}

int main(void) {
    struct Student students[MAX_STUDENTS] = { {0, "", 0.0} };
    const struct Student a = { 101, "Asha Rao", 91.5 };
    const struct Student duplicate = { 101, "Duplicate", 70.0 };
    const struct Student b = { 102, "Ravi Kumar", 82.0 };
    const struct Student c = { 103, "Mina Das", 76.0 };
    const struct Student d = { 104, "Full Check", 88.0 };
    size_t count = 0U;

    assert(add_student(students, &count, &a) == OK);
    assert(add_student(students, &count, &duplicate) == DUPLICATE_ID);
    assert(add_student(students, &count, &b) == OK);
    assert(add_student(students, &count, &c) == OK);
    assert(add_student(students, &count, &d) == FULL);
    assert(find_student(students, count, 102) == 1U);
    assert(find_student(students, count, 999) == count);
    assert(update_marks(students, count, 102, 95.0) == OK);
    assert(students[1].marks == 95.0);
    assert(update_marks(students, count, 102, 101.0) == INVALID);
    assert(delete_student(students, &count, 101) == OK);
    assert(count == 2U && students[0].id == 102);
    assert(delete_student(students, &count, 999) == NOT_FOUND);
    puts("All student record tests passed.");
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STUDENTS 100
#define NAME_SIZE 64
#define LINE_SIZE 128

struct Student {
    int id;
    char name[NAME_SIZE];
    double marks;
};

enum ReadResult { READ_OK, READ_END, READ_INVALID };

static enum ReadResult read_line(const char *prompt, char *buffer, size_t size) {
    size_t length;
    int ch;
    if (prompt != NULL) fputs(prompt, stdout);
    if (fgets(buffer, (int)size, stdin) == NULL) return READ_END;
    length = strlen(buffer);
    if (length > 0U && buffer[length - 1U] == '\n') {
        buffer[length - 1U] = '\0';
        return READ_OK;
    }
    ch = getchar();
    if (ch == '\n' || ch == EOF) return READ_OK;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return READ_INVALID;
}

static char *trim(char *text) {
    char *start = text;
    char *end;
    while (isspace((unsigned char)*start)) ++start;
    end = start + strlen(start);
    while (end > start && isspace((unsigned char)end[-1])) --end;
    *end = '\0';
    return start;
}

static int read_integer(const char *prompt, int *value) {
    char line[LINE_SIZE];
    char *end;
    long parsed;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    errno = 0;
    {
        char *start = trim(line);
        parsed = strtol(start, &end, 10);
        if (end == start || errno == ERANGE || parsed < 1L || parsed > 2147483647L) return -1;
    }
    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0') return -1;
    *value = (int)parsed;
    return 1;
}

static int read_marks(const char *prompt, double *value) {
    char line[LINE_SIZE];
    char *start;
    char *end;
    double parsed;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    start = trim(line);
    errno = 0;
    parsed = strtod(start, &end);
    if (end == start || errno == ERANGE || !isfinite(parsed)) return -1;
    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0' || parsed < 0.0 || parsed > 100.0) return -1;
    *value = parsed;
    return 1;
}

static int read_name(const char *prompt, char name[NAME_SIZE]) {
    char line[LINE_SIZE];
    char *clean;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    size_t length;
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    clean = trim(line);
    length = strlen(clean);
    if (length == 0U || length >= NAME_SIZE) return -1;
    memcpy(name, clean, length + 1U);
    return 1;
}

static size_t find_student(const struct Student students[], size_t count, int id) {
    size_t i;
    for (i = 0; i < count; ++i) if (students[i].id == id) return i;
    return count;
}

static void list_students(const struct Student students[], size_t count) {
    size_t i;
    if (count == 0U) {
        puts("No student records.");
        return;
    }
    puts("\nID       NAME                                     MARKS");
    for (i = 0; i < count; ++i)
        printf("%-8d %-40s %6.2f\n", students[i].id, students[i].name, students[i].marks);
}

static void add_student(struct Student students[], size_t *count) {
    struct Student item;
    int status;
    if (*count >= MAX_STUDENTS) {
        puts("Storage is full.");
        return;
    }
    status = read_integer("Student ID: ", &item.id);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    if (find_student(students, *count, item.id) != *count) {
        puts("That ID already exists.");
        return;
    }
    status = read_name("Student name: ", item.name);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid name or line too long."); return; }
    status = read_marks("Marks (0-100): ", &item.marks);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid marks."); return; }
    students[*count] = item;
    ++(*count);
    puts("Student added.");
}

static void search_student(const struct Student students[], size_t count) {
    int id;
    int status = read_integer("ID to find: ", &id);
    size_t index;
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_student(students, count, id);
    if (index == count) puts("Student not found.");
    else printf("Found: %d | %s | %.2f\n", students[index].id,
                students[index].name, students[index].marks);
}

static void update_student(struct Student students[], size_t count) {
    int id;
    int status = read_integer("ID to update: ", &id);
    size_t index;
    double marks;
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_student(students, count, id);
    if (index == count) { puts("Student not found."); return; }
    status = read_marks("New marks (0-100): ", &marks);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid marks."); return; }
    students[index].marks = marks;
    puts("Marks updated.");
}

static void delete_student(struct Student students[], size_t *count) {
    int id;
    int status = read_integer("ID to delete: ", &id);
    size_t index;
    size_t i;
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_student(students, *count, id);
    if (index == *count) { puts("Student not found."); return; }
    for (i = index; i + 1U < *count; ++i) students[i] = students[i + 1U];
    --(*count);
    puts("Student deleted.");
}

int main(void) {
    struct Student students[MAX_STUDENTS];
    size_t count = 0U;
    char line[LINE_SIZE];
    int choice;
    for (;;) {
        enum ReadResult status;
        puts("\nSTUDENT RECORD MANAGER");
        puts("1 Add  2 List  3 Search  4 Update marks  5 Delete  0 Exit");
        status = read_line("Choose: ", line, sizeof line);
        if (status != READ_OK) {
            if (status == READ_END) puts("\nEnd of input. Goodbye.");
            else puts("Invalid or overlong menu input.");
            if (status == READ_END) break;
            continue;
        }
        {
            char *end;
            long parsed;
            char *start = trim(line);
            errno = 0;
            parsed = strtol(start, &end, 10);
            while (isspace((unsigned char)*end)) ++end;
            if (start == end || *end != '\0' || errno == ERANGE
                || parsed < 0L || parsed > 5L) {
                puts("Choose a number from 0 to 5.");
                continue;
            }
            choice = (int)parsed;
        }
        switch (choice) {
            case 1: add_student(students, &count); break;
            case 2: list_students(students, count); break;
            case 3: search_student(students, count); break;
            case 4: update_student(students, count); break;
            case 5: delete_student(students, &count); break;
            case 0: puts("Goodbye."); return 0;
            default: break;
        }
    }
    return 0;
}
